const HD_DOMAIN: [u8; 4] = [0x50, 0x56, 0x48, 0x01];
/// The FROZEN v0.5 / CANDIDATE v0.7-payment token-agent leaf tag (IDENTICAL
/// domain in both — v0.7-payment carries the flat leaf format unchanged).
const FLAT_DOMAIN: [u8; 4] = [0x50, 0x56, 0x35, 0x01];
const RECIP_DOMAIN: [u8; 4] = [0x50, 0x56, 0x33, 0x01];
const ZERO32: [u8; 32] = [0u8; 32];
const VAULT_ID: [u8; 32] = [0x44; 32];
const ALT_VAULT_ID: [u8; 32] = [0x45; 32];
