#[derive(Clone, Debug, PartialEq)]
struct S {
    reserve: i64,
    paused: i64,
    agent_root: [u8; 32],
    policy_nonce: i64,
}
fn templated(src: &str, s: &S) -> String {
    let mut src = src.to_string();
    let mut r = |from: &str, to: String| {
        assert!(src.contains(from), "anchor missing: {from}");
        src = src.replacen(from, &to, 1);
    };
    r("int feeReserve = initFeeReserve;", format!("int feeReserve = {};", s.reserve));
    r("int paused = 0;", format!("int paused = {};", s.paused));
    r("byte[32] agentRoot = initAgentRoot;", format!("byte[32] agentRoot = 0x{};", hx(&s.agent_root)));
    r("int policyNonce = 0;", format!("int policyNonce = {};", s.policy_nonce));
    src
}
#[derive(Clone)]
struct TokenPin {
    token_covid: Hash,
    template_hash: [u8; 32],
    prefix_len: i64,
    state_len: i64,
    suffix_len: i64,
}
fn token_pin() -> TokenPin {
    let sample = compile_kcc20(COV_CTRL.as_bytes().try_into().unwrap(), IDENTIFIER_COVENANT_ID, PREV_TOKEN_AMOUNT, false, 2);
    let t = template_of(&sample);
    TokenPin { token_covid: COV_TOKEN, template_hash: t.hash, prefix_len: t.prefix.len() as i64, state_len: t.state_len as i64, suffix_len: t.suffix.len() as i64 }
}

const RECOVERY_PK_SEED: u8 = 0x51;
fn recovery_pk() -> [u8; 32] {
    xonly(&kp(RECOVERY_PK_SEED))
}

/// Compile `contracts/PolicyVault.v0.7-payment-hd.sil` (contract
/// `PolicyVaultRootedTokenHD`) with the exact live state baked in.
fn compile_ctrl(src: &str, tok: &TokenPin, root: &RootPin, s: &S, vault_id: &[u8; 32]) -> CompiledContract<'static> {
    let src: &'static str = leak(templated(src, s));
    compile_contract(
        src,
        &[
            Expr::bytes(vault_id.to_vec()),
            Expr::bytes(DESCRIPTOR_HASH.to_vec()),
            Expr::bytes(tok.token_covid.as_bytes().to_vec()),
            Expr::bytes(tok.template_hash.to_vec()),
            Expr::int(tok.prefix_len),
            Expr::int(tok.state_len),
            Expr::int(tok.suffix_len),
            Expr::bytes(root.covid.as_bytes().to_vec()),
            Expr::bytes(root.hash.to_vec()),
            Expr::int(root.prefix_len),
            Expr::int(root.state_len),
            Expr::int(root.suffix_len),
            Expr::bytes(recovery_pk().to_vec()),
            Expr::bytes(s.agent_root.to_vec()),
            Expr::int(s.reserve),
        ],
        CompileOptions::default(),
    )
    .unwrap_or_else(|e| panic!("HD rooted compile: {e:?}"))
}
fn state_arg(s: &S, vault_id: &[u8; 32]) -> Expr<'static> {
    struct_object(vec![
        ("boundVaultId", Expr::bytes(vault_id.to_vec())),
        ("feeReserve", Expr::int(s.reserve)),
        ("paused", Expr::int(s.paused)),
        ("agentRoot", Expr::bytes(s.agent_root.to_vec())),
        ("policyNonce", Expr::int(s.policy_nonce)),
    ])
}

/// Standing pin: one root template + pin, shared by every test in this file
/// so the vault's compiled `rootTemplateVmHash`/lengths are consistent.
fn standing_root_pin() -> (RootTemplate, RootPin) {
    let tmpl = RootTemplate::default();
    let pin = root_pin(COV_ROOT, &tmpl);
    (tmpl, pin)
}

