#[test]
fn hd_rooted_honest_revocation_then_child_spend_refused() {
    let mut c = honest_spend(2);
    c.op = Op::Dsc;
    c.entry = 1;
    c.slice_end_anchored = false;
    c.signer_seed = A1_SEED;
    c.dsc_new_child_root = ZERO32;
    let revoked = accepts("revocation (parent zeroes childRoot)", &c);
    let mut bare = c.tree.clone();
    bare.depth = 1;
    assert_eq!(revoked.new_root, forest_root_of(&bare), "revocation must refold to the childless agentRoot");
    let mut spend = honest_spend(2);
    spend.prev_root_override = Some(forest_root_of(&bare));
    let (ctrl, _) = run(&spend);
    assert!(ctrl.is_err(), "a revoked child must not be able to spend: {ctrl:?}");
}

#[test]
fn hd_rooted_honest_parent_budget_is_shared_across_siblings() {
    let mut c = honest_spend(2);
    c.tree.l1[0].period_budget = 300;
    c.tree.l1[0].period_spent = 200;
    c.tree.l2[0].period_spent = 200;
    c.tree.l2_target = 1;
    c.signer_seed = BSIB_SEED;
    c.spend = 100;
    accepts("sibling spends the parent's remaining budget", &c);
    let mut over = c.clone();
    over.spend = 101;
    assert!(run(&over).0.is_err(), "sibling must not exceed the parent's remaining budget");
}

/* ---- rooted owner paths — carried over BYTE-IDENTICAL from v0.7-payment ---- */

fn honest_root_and_vault() -> (RootState, RootTemplate, S) {
    let root = RootState::with(3, 2, 1, 2);
    let (tmpl, _pin) = standing_root_pin();
    let vault = S { reserve: RESERVE, paused: 0, agent_root: [0x11; 32], policy_nonce: 0 };
    (root, tmpl, vault)
}

/// Build + sign + run one ownerControl(sel) call under a root AUTHORIZE (or,
/// for sel==4, a root FREEZE). Returns (vault_result, root_result, new_vault_state).
fn run_owner_control(sel: i64, root_signers: &[usize], vault_prev: &S, vault_new_override: Option<S>) -> (Result<(), TxScriptError>, Result<(), TxScriptError>, S) {
    let (root_prev, tmpl, _) = honest_root_and_vault();
    let (tok, rpin) = (token_pin(), root_pin(COV_ROOT, &tmpl));
    let ctrl_prev = compile_ctrl(src_ctrl_raw(), &tok, &rpin, vault_prev, &VAULT_ID);
    let vault_new = vault_new_override.unwrap_or_else(|| match sel {
        0 => S { agent_root: [0x99; 32], policy_nonce: vault_prev.policy_nonce + 1, ..vault_prev.clone() },
        1 => S { reserve: vault_prev.reserve + KAS, ..vault_prev.clone() },
        2 => S { paused: 1, ..vault_prev.clone() },
        3 => S { paused: 0, ..vault_prev.clone() },
        4 => S { paused: 1, ..vault_prev.clone() },
        _ => panic!("bad selector"),
    });
    let ctrl_next = compile_ctrl(src_ctrl_raw(), &tok, &rpin, &vault_new, &VAULT_ID);
    let expect_frozen = if sel == 4 { 1 } else { 0 };
    let root_new = RootState { frozen: expect_frozen, ..root_prev.advanced() };
    let root_next = compile_root(&root_new, &tmpl);

    /* topUpReserve (selector 1) increases the vault's successor value; that
     * extra value must be FUNDED by an external input (core/model
     * vault-transitions-v7.js's `externalFunding`), never manufactured. The
     * fuel input simply carries the extra amount through to the vault's
     * output; fuel's own change is unaffected — conservation holds for
     * every selector by construction. */
    let top_up = (vault_new.reserve - vault_prev.reserve).max(0);
    let entries = vec![cov_utxo(vault_prev.reserve, &ctrl_prev, COV_CTRL), cov_utxo(ROOT_KAS, &compile_root(&root_prev, &tmpl), COV_ROOT), UtxoEntry::new((FUEL + top_up) as u64, p2pk_spk(&xonly(&fuel_kp())), 0, false, None)];
    let outputs = vec![cov_out(vault_new.reserve, &ctrl_next, 0, COV_CTRL), cov_out(ROOT_KAS - ROOT_FEE_PAID, &root_next, 1, COV_ROOT), p2pk_out(&xonly(&fuel_kp()), FUEL - ROOT_FEE_PAID)];
    let inputs = vec![input(1, 0, vec![], 400), input(2, 0, vec![], 400), input(3, 0, vec![], 20)];
    let unsigned = Transaction::new(1, inputs.clone(), outputs.clone(), 0, SubnetworkId::default(), 0, vec![]);

    let signers: Vec<(usize, Keypair)> = root_signers.iter().map(|i| (*i, kp(OWNER_SEEDS[*i]))).collect();
    let blob = root_owner_blob(&unsigned, &entries, 1, &signers);
    /* root action 0 = AUTHORIZE (full quorum, ownerM); root action 2 = FREEZE
     * (the lighter emergency quorum, emergencyK) — selector 4 (EMERGENCY
     * pause) is the ONLY vault op reachable from a root FREEZE. */
    let root_action = if sel == 4 { 2i64 } else { 0i64 };
    let root_ss = cov_call_opt(&compile_root(&root_prev, &tmpl), "rootAction", vec![root_state_arg(&root_new), Expr::int(root_action), Expr::bytes(blob)], false);
    let ctrl_ss = cov_call_opt(&ctrl_prev, "ownerControl", vec![state_arg(&vault_new, &VAULT_ID), Expr::int(sel)], false);
    let fuel_sig = sign_typed(&unsigned, &entries, 2, &fuel_kp(), SIG_HASH_ALL);

    let mut signed = inputs;
    signed[0].signature_script = ctrl_ss;
    signed[1].signature_script = root_ss;
    signed[2].signature_script = p2pk_sigscript(fuel_sig);
    let tx = Transaction::new(1, signed, outputs, 0, SubnetworkId::default(), 0, vec![]);
    let vr = execute_input_with_covenants(tx.clone(), entries.clone(), 0);
    let rr = execute_input_with_covenants(tx, entries, 1);
    (vr, rr, vault_new)
}

#[test]
fn hd_rooted_honest_owner_control_selectors_0_to_4_accept() {
    let (_, _tmpl, vault_prev) = honest_root_and_vault();
    for sel in 0..=4i64 {
        let signers: Vec<usize> = if sel == 4 { vec![0] } else { vec![0, 1] };
        let vp = if sel == 3 { S { paused: 1, ..vault_prev.clone() } } else { vault_prev.clone() };
        let (vr, rr, _) = run_owner_control(sel, &signers, &vp, None);
        vr.unwrap_or_else(|e| panic!("ownerControl({sel}) vault must accept: {e:?}"));
        rr.unwrap_or_else(|e| panic!("ownerControl({sel}) root must accept: {e:?}"));
    }
}

#[test]
fn hd_rooted_owner_control_under_full_quorum_pause_then_delegation_refused() {
    /* END-TO-END composition proof for the design freeze's binding rule: "the
     * FROZEN root state must refuse delegation operations exactly as `paused`
     * does". No HD entrypoint checks the root directly (that would cost the
     * whole requireRootAuthorization block on the delegate/child-spend path);
     * instead a root FREEZE reaches delegation THROUGH the vault's own
     * `paused` flag via ownerControl selector 4 (EMERGENCY pause). */
    let (_, _tmpl, vault_prev) = honest_root_and_vault();
    let (vr, rr, vault_new) = run_owner_control(4, &[0], &vault_prev, None);
    vr.expect("EMERGENCY pause (selector 4) under root FREEZE must accept on the vault");
    rr.expect("root FREEZE must accept");
    assert_eq!(vault_new.paused, 1);

    /* now a delegation attempt against the just-paused vault must refuse */
    let mut c = honest_dsc(1).0;
    c.prev_paused = 1;
    c.prev_root_override = None; // uses the honest tree's own agentRoot; only paused changed
    let (ctrl, _) = run(&c);
    assert!(ctrl.is_err(), "delegation must be refused once the vault is paused by the root's FREEZE path: {ctrl:?}");
    println!("  REFUSED delegation against a root-FREEZE-triggered paused vault          {:?}", ctrl.unwrap_err());

    /* and a child spend against the same paused vault */
    let mut spend = honest_spend(2);
    spend.prev_paused = 1;
    let (ctrl2, _) = run(&spend);
    assert!(ctrl2.is_err(), "a spend must also be refused once the vault is paused by the root's FREEZE path: {ctrl2:?}");
}

#[test]
fn hd_rooted_honest_owner_recover_to_the_genesis_pinned_destination() {
    let (root_prev, tmpl, vault_prev) = honest_root_and_vault();
    let (tok, rpin) = (token_pin(), root_pin(COV_ROOT, &tmpl));
    let ctrl_prev = compile_ctrl(src_ctrl_raw(), &tok, &rpin, &vault_prev, &VAULT_ID);
    let root_new = root_prev.advanced();
    let root_next = compile_root(&root_new, &tmpl);
    let rec_pk = recovery_pk();

    let tok_prev = compile_kcc20(COV_CTRL.as_bytes().try_into().unwrap(), IDENTIFIER_COVENANT_ID, PREV_TOKEN_AMOUNT, false, 2);
    let tok_out = compile_kcc20(rec_pk, IDENTIFIER_PUBKEY, PREV_TOKEN_AMOUNT, false, 2);

    let entries = vec![
        cov_utxo(vault_prev.reserve, &ctrl_prev, COV_CTRL),
        cov_utxo(ROOT_KAS, &compile_root(&root_prev, &tmpl), COV_ROOT),
        cov_utxo(TOKEN_CARRY, &tok_prev, COV_TOKEN),
        UtxoEntry::new(FUEL as u64, p2pk_spk(&xonly(&fuel_kp())), 0, false, None),
    ];
    let outputs = vec![p2pk_out(&rec_pk, vault_prev.reserve), cov_out(ROOT_KAS - ROOT_FEE_PAID, &root_next, 1, COV_ROOT), cov_out(TOKEN_CARRY, &tok_out, 2, COV_TOKEN), p2pk_out(&xonly(&fuel_kp()), FUEL - ROOT_FEE_PAID)];
    let inputs = vec![input(1, 0, vec![], 400), input(2, 0, vec![], 400), input(3, 0, vec![], 200), input(4, 0, vec![], 20)];
    let unsigned = Transaction::new(1, inputs.clone(), outputs.clone(), 0, SubnetworkId::default(), 0, vec![]);

    let signers: Vec<(usize, Keypair)> = vec![(0, kp(OWNER_SEEDS[0])), (1, kp(OWNER_SEEDS[1]))];
    let blob = root_owner_blob(&unsigned, &entries, 1, &signers);
    let root_ss = cov_call_opt(&compile_root(&root_prev, &tmpl), "rootAction", vec![root_state_arg(&root_new), Expr::int(0), Expr::bytes(blob)], false);
    let ctrl_ss = cov_call_opt(&ctrl_prev, "ownerRecover", vec![Vec::<Expr<'static>>::new().into(), kcc20_state(rec_pk, IDENTIFIER_PUBKEY, PREV_TOKEN_AMOUNT, false)], false);
    let tok_ss = cov_call_opt(&tok_prev, "transfer", vec![vec![kcc20_state(rec_pk, IDENTIFIER_PUBKEY, PREV_TOKEN_AMOUNT, false)].into(), Vec::<Expr>::new().into(), Expr::bytes(vec![0u8])], true);
    let fuel_sig = sign_typed(&unsigned, &entries, 3, &fuel_kp(), SIG_HASH_ALL);

    let mut signed = inputs;
    signed[0].signature_script = ctrl_ss;
    signed[1].signature_script = root_ss;
    signed[2].signature_script = tok_ss;
    signed[3].signature_script = p2pk_sigscript(fuel_sig);
    let tx = Transaction::new(1, signed, outputs, 0, SubnetworkId::default(), 0, vec![]);
    for i in 0..4 {
        execute_input_with_covenants(tx.clone(), entries.clone(), i).unwrap_or_else(|e| panic!("ownerRecover input {i} must accept: {e:?}"));
    }
}

