#[test]
fn hd_rooted_hostile_matrix_spend_refuses_every_class() {
    let mut failures: Vec<String> = Vec::new();
    let mut refusals: Vec<(String, String)> = Vec::new();
    let outsider = xonly(&kp(OUTSIDER_SEED));

    {
        let mut c = honest_spend(3);
        c.tree.l3[0].max_per_spend = 400;
        c.tree.l3[0].period_budget = 1000;
        c.tree.l2[0].max_per_spend = 400;
        c.tree.l2[0].period_budget = 1000;
        c.spend = 300;
        refuse("child cap > parent cap (spend inside the child's own cap)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.tree.l3[0].period_budget = 1000;
        c.tree.l2[0].period_budget = 1000;
        c.tree.l1[0].period_spent = 350;
        refuse("child budget > ancestor period budget (parent counter binds)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        set_recip(&mut c, 0, 0, outsider);
        refuse("narrower child allowlist honest / broader forged: recipient allowed by the child but NOT by the grandparent", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        set_recip(&mut c, 1, 0, outsider);
        refuse("recipient allowed by the child but NOT by the parent", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.tree.l3[0].max_fee_per_tx = 100_000;
        c.tree.l1[0].max_fee_per_tx = 20_000;
        c.reserve_consumed = 30_000;
        refuse("child fee cap > parent fee cap (min over the chain binds)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.tree.l3[0].max_carry_kas = KAS;
        c.tree.l1[0].max_carry_kas = KAS / 20;
        c.recipient_carry = KAS / 10;
        refuse("child carry cap > parent carry cap (min over the chain binds)", &c, &mut failures, &mut refusals);
    }
    for skip in [0usize, 1] {
        let mut c = honest_spend(3);
        c.cheat_unadvanced_level = Some(skip);
        refuse(&format!("spend without advancing the level-{} counter in the refold", skip + 1), &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.new_root_override = Some([0x55; 32]);
        refuse("successor agentRoot misreport", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(2);
        c.tree.l1[0].period_budget = 300;
        c.tree.l1[0].period_spent = 200;
        c.tree.l2[0].period_spent = 200;
        c.tree.l2_target = 1;
        c.signer_seed = BSIB_SEED;
        c.spend = 200;
        refuse("sibling budget interaction: double-count beyond the shared parent budget", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.tree.l1[0].period_spent = 200;
        let mut stale = committed_leaf(&c.tree, 0);
        stale.period_spent = 0;
        c.claim.push((0, stale));
        refuse("parent period-accounting misreport (claimed spent 0)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        let mut moved = c.tree.clone();
        moved.l1[0].period_spent += 50;
        c.prev_root_override = Some(forest_root_of(&moved));
        refuse("stale parent proof (committed counters already advanced)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        let mut removed = c.tree.clone();
        removed.l1 = vec![removed.l1[1].clone()];
        removed.l1_target = 0;
        removed.depth = 1;
        c.prev_root_override = Some(forest_root_of(&removed));
        refuse("removed parent (removed grandparent, reused parent chain)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        let mut bare = c.tree.clone();
        bare.depth = 2;
        c.prev_root_override = Some(forest_root_of(&bare));
        refuse("child-root substitution / revoked subtree (parent childRoot zeroed)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        let mut z = committed_leaf(&c.tree, 1);
        z.child_root = ZERO32;
        c.claim.push((1, z));
        refuse("ancestor presented with a zero childRoot", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(2);
        c.entry = 1;
        refuse("level confusion: level-2 key presented as level-1 (hdSpend)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.entry = 2;
        refuse("level confusion: chain shorter than the leaf level (childSpendL2 with a level-3 leaf)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.tree.l3[0].level = 2;
        refuse("level confusion: leaf committed at a different level than its chain position", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.tree.depth = 4;
        c.entry = 3;
        c.signer_seed = 0x6a;
        c.spend = 100;
        refuse("> MAX_LEVEL chain (level-4 leaf through childSpendL3)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.tree.l2[0].pk = xonly(&kp(A1_SEED));
        refuse("self-parenting (parent key reused as the child key)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.tree.l3[0].pk = xonly(&kp(A1_SEED));
        c.signer_seed = A1_SEED;
        refuse("grandparent key reused as the spending leaf key", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(1);
        c.flat_format_tree = true;
        refuse("domain-tag confusion: v0.5/v0.7-payment flat leaf tag committed, HD leaf presented (hdSpend)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.tree.l3[0].expiry_daa = 9_500_000;
        refuse("expiry inversion (child expiryDaa > parent expiryDaa)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.tree.l2[0].expiry_daa = 9_500_000;
        refuse("expiry inversion (parent expiryDaa > grandparent expiryDaa)", &c, &mut failures, &mut refusals);
    }
    for (label, seed) in [("outsider key", OUTSIDER_SEED), ("the PARENT's key on the child's spend", B_SEED), ("the (nonexistent) owner key", 0x61u8)] {
        let mut c = honest_spend(3);
        c.signer_seed = seed;
        refuse(&format!("descendant/wrong signer ({label})"), &c, &mut failures, &mut refusals);
    }
    for (label, ty) in [("NONE", SIG_HASH_NONE), ("SINGLE", SIG_HASH_SINGLE), ("ANYONECANPAY", SIG_HASH_ANY_ONE_CAN_PAY)] {
        let mut c = honest_spend(3);
        c.sighash = ty;
        refuse(&format!("SIGHASH_{label} + forged gate byte on a level-3 spend"), &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.mutate_after_sign = true;
        refuse("post-sign mutation of an output value", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.reserve_consumed = FEE + 1;
        refuse("fee-domain abuse: fee-reserve consumed above the exact network fee", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.succ_value_override = Some(RESERVE - RESERVE_CONSUMED - 1_000_000);
        refuse("fee-domain abuse: successor value below the declared reserve", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.succ_reserve_override = Some(RESERVE + 1);
        refuse("fee-domain abuse: declared successor reserve inflated", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.self_carry_override = Some(TOKEN_CARRY - RECIPIENT_CARRY - 1);
        refuse("token-domain abuse: token-family KAS leaked to change", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.self_amount_delta = 1;
        refuse("token-domain abuse: token conservation (+1)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.prev_paused = 1;
        refuse("paused vault (level-3 spend)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.succ_paused_override = Some(1);
        refuse("spend flipping the vault to paused", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.succ_nonce_override = Some(1);
        refuse("spend bumping the owner policy nonce", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.succ_vault_id_override = Some(ALT_VAULT_ID);
        refuse("spend rebinding the vault id", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.recipient_type = IDENTIFIER_COVENANT_ID;
        refuse("recipient owned by the covenant-id scheme instead of p2pk", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.recipient_override = Some(outsider);
        refuse("recipient outside every allowlist", &c, &mut failures, &mut refusals);
    }
    {
        /* malformed body: 159 bytes (one short) */
        let mut c = honest_spend(1);
        let mut raw = hd_leaf_body(&committed_leaf(&c.tree, 0));
        raw.truncate(159);
        c.raw_leaf_override = Some((0, raw));
        refuse("malformed HD leaf body (159 bytes)", &c, &mut failures, &mut refusals);
    }
    {
        /* malformed body: 161 bytes (one extra) */
        let mut c = honest_spend(1);
        let mut raw = hd_leaf_body(&committed_leaf(&c.tree, 0));
        raw.push(0x00);
        c.raw_leaf_override = Some((0, raw));
        refuse("malformed HD leaf body (161 bytes)", &c, &mut failures, &mut refusals);
    }
    {
        /* wrong field order: swap maxPerSpend and periodBudget (both still
         * 160 B, so only the length guard cannot catch this — the leaf
         * simply fails to hash to the committed membership root) */
        let mut c = honest_spend(1);
        let mut raw = hd_leaf_body(&committed_leaf(&c.tree, 0));
        raw.swap(32, 40);
        raw.swap(33, 41);
        raw.swap(34, 42);
        raw.swap(35, 43);
        c.raw_leaf_override = Some((0, raw));
        refuse("malformed HD leaf body (wrong field order)", &c, &mut failures, &mut refusals);
    }
    {
        /* altered nested refold: forge the intermediate subtree root fed
         * into the level-1 fold on a level-2 spend (a level-3-style attack
         * shape ported down to level 2 for a self-contained refold check) */
        let mut c = honest_spend(2);
        let (tree, path) = c.tree.materialize();
        let chain = chain_proofs(&tree, &path);
        let (a1, sibs1, bits1) = &chain[0];
        let mut nl = a1.clone();
        nl.period_start_daa = a1.period_start_daa;
        nl.period_spent = a1.period_spent + c.spend;
        nl.child_root = [0x77; 32]; // forged subtree root, not the real fold of B's advance
        c.new_root_override = Some(fold(hd_leaf_hash(&nl), sibs1, *bits1));
        refuse("altered nested refold (forged intermediate subtree root)", &c, &mut failures, &mut refusals);
    }
    {
        /* budget rollover at multiple levels: BOTH the child and the parent
         * legitimately roll over in the SAME spend (lock_time satisfies both
         * boundaries — this alone is honest and not refused), but the
         * refold is forged to skip advancing the PARENT's counter despite
         * its own claimed rollover. Combines the multi-level-rollover shape
         * with the counter-forgery class (§3) to prove the refold binds
         * every level even when more than one clock ticks over at once. */
        let mut c = honest_spend(3);
        c.periods_elapsed[2] = 1; // C rolls over: 5400 + 500 = 5900
        c.periods_elapsed[0] = 1; // A1 ALSO rolls over: 5000 + 1000 = 6000
        c.lock_time = 6000; // satisfies both boundaries
        c.tree.l3[0].period_spent = 400; // irrelevant post-rollover, but inside cap pre-check
        c.cheat_unadvanced_level = Some(0); // forge: A1's counters NOT actually advanced in the refold
        refuse("budget rollover at multiple levels with a forged unadvanced ancestor counter", &c, &mut failures, &mut refusals);
    }

    assert!(failures.is_empty(), "hierarchical-delegation (rooted) hostile spend-matrix failures:\n{}", failures.join("\n"));
    println!("\n  rooted hostile spend rows refused: {}", refusals.len());
}

