#[test]
fn hd_rooted_hostile_matrix_delegation_refuses_every_class() {
    let mut failures: Vec<String> = Vec::new();
    let mut refusals: Vec<(String, String)> = Vec::new();

    let base1 = || honest_dsc(1).0;
    let base2 = || honest_dsc(2).0;

    for (label, seed) in [("a sibling level-1 leaf's key", OTHER_L1_SEED), ("the child's key", B_SEED), ("a grandchild's key", C_SEED), ("the (nonexistent) vault owner key", 0x61u8), ("an outsider key", OUTSIDER_SEED)] {
        let mut c = base1();
        c.signer_seed = seed;
        refuse(&format!("delegateSetChildRoot1 signed by {label}"), &c, &mut failures, &mut refusals);
    }
    {
        let mut c = base2();
        c.signer_seed = A1_SEED;
        refuse("delegateSetChildRoot2 signed by the grandparent", &c, &mut failures, &mut refusals);
    }
    let field_mutators: Vec<(&str, fn(&mut Scen))> = vec![
        ("feeReserve", |c: &mut Scen| c.succ_reserve_override = Some(RESERVE - 1)),
        ("paused", |c: &mut Scen| c.succ_paused_override = Some(1)),
        ("policyNonce", |c: &mut Scen| c.succ_nonce_override = Some(1)),
        ("boundVaultId", |c: &mut Scen| c.succ_vault_id_override = Some(ALT_VAULT_ID)),
        ("successor output value", |c: &mut Scen| c.succ_value_override = Some(RESERVE - 1)),
    ];
    for (label, f) in field_mutators {
        let mut c = base1();
        f(&mut c);
        refuse(&format!("delegateSetChildRoot1 also changing {label}"), &c, &mut failures, &mut refusals);
    }
    {
        let mut c = base1();
        let (tree, path) = c.tree.materialize();
        let chain = chain_proofs(&tree, &path);
        let mut raised = chain[0].0.clone();
        raised.max_per_spend = 100_000;
        raised.child_root = c.dsc_new_child_root;
        c.new_root_override = Some(fold(hd_leaf_hash(&raised), &chain[0].1, chain[0].2));
        refuse("delegateSetChildRoot1 raising the parent's own cap in the refold", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = base1();
        c.new_root_override = Some([0x33; 32]);
        refuse("delegateSetChildRoot1 successor root misreport", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = base1();
        c.prev_paused = 1;
        c.succ_paused_override = Some(1);
        refuse("delegation while the vault is PAUSED (OQ-HD-3, composed with the rooted vault)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = base1();
        c.dsc_tokens_ride = true;
        refuse("tokens riding a delegation op", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = base2();
        c.entry = 1;
        c.slice_end_anchored = true;
        refuse("level-2 parent presented to delegateSetChildRoot1 (level confusion)", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = honest_spend(3);
        c.op = Op::Dsc;
        c.entry = 2;
        c.slice_end_anchored = true;
        c.signer_seed = C_SEED;
        c.dsc_new_child_root = [0x9a; 32];
        refuse("level-3 leaf attempting delegateSetChildRoot2 (> MAX_LEVEL delegation)", &c, &mut failures, &mut refusals);
    }
    for (label, ty) in [("NONE", SIG_HASH_NONE), ("SINGLE", SIG_HASH_SINGLE), ("ANYONECANPAY", SIG_HASH_ANY_ONE_CAN_PAY)] {
        let mut c = base1();
        c.sighash = ty;
        refuse(&format!("SIGHASH_{label} + forged gate byte on delegateSetChildRoot1"), &c, &mut failures, &mut refusals);
    }
    {
        let mut c = base1();
        c.mutate_after_sign = true;
        refuse("post-sign mutation on delegateSetChildRoot1", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = base1();
        let mut moved = c.tree.clone();
        moved.l1[0].period_spent += 50;
        c.prev_root_override = Some(forest_root_of(&moved));
        refuse("delegateSetChildRoot1 against a stale parent proof", &c, &mut failures, &mut refusals);
    }
    {
        let mut c = base2();
        let mut removed = c.tree.clone();
        removed.l1 = vec![removed.l1[1].clone()];
        removed.l1_target = 0;
        removed.depth = 1;
        c.prev_root_override = Some(forest_root_of(&removed));
        refuse("delegateSetChildRoot2 with a removed parent (grandparent)", &c, &mut failures, &mut refusals);
    }

    assert!(failures.is_empty(), "hierarchical-delegation (rooted) hostile delegation-matrix failures:\n{}", failures.join("\n"));
    println!("\n  rooted hostile delegation rows refused: {}", refusals.len());
}

/* ================================================================== */
/* descendant attempting an owner / root operation                      */
/* ================================================================== */

#[test]
fn hd_rooted_descendant_cannot_forge_an_owner_or_root_operation() {
    /* A level-2 delegate's key is not among the root's pinned owner slots by
     * construction (disjoint key material) and no HD entrypoint ever reaches
     * ownerControl/ownerRecover. The only way a descendant could attempt an
     * owner/root operation at all is by trying to satisfy the ROOT's own
     * M-of-N with its leaf key — which the root's own pinned owner pubkeys
     * refuse. This is the vault-side face of that boundary: the ROOT input
     * must reject when "signed" with a descendant's key. */
    let (root_prev, tmpl, vault_prev) = honest_root_and_vault();
    let (tok, rpin) = (token_pin(), root_pin(COV_ROOT, &tmpl));
    let ctrl_prev = compile_ctrl(src_ctrl_raw(), &tok, &rpin, &vault_prev, &VAULT_ID);
    let vault_new = S { agent_root: [0x99; 32], policy_nonce: 1, ..vault_prev.clone() };
    let ctrl_next = compile_ctrl(src_ctrl_raw(), &tok, &rpin, &vault_new, &VAULT_ID);
    let root_new = root_prev.advanced();
    let root_next = compile_root(&root_new, &tmpl);

    let entries = vec![cov_utxo(vault_prev.reserve, &ctrl_prev, COV_CTRL), cov_utxo(ROOT_KAS, &compile_root(&root_prev, &tmpl), COV_ROOT), UtxoEntry::new(FUEL as u64, p2pk_spk(&xonly(&fuel_kp())), 0, false, None)];
    let outputs = vec![cov_out(vault_new.reserve, &ctrl_next, 0, COV_CTRL), cov_out(ROOT_KAS - ROOT_FEE_PAID, &root_next, 1, COV_ROOT), p2pk_out(&xonly(&fuel_kp()), FUEL - ROOT_FEE_PAID)];
    let inputs = vec![input(1, 0, vec![], 400), input(2, 0, vec![], 400), input(3, 0, vec![], 20)];
    let unsigned = Transaction::new(1, inputs.clone(), outputs.clone(), 0, SubnetworkId::default(), 0, vec![]);

    /* the level-2 delegate B's key stands in for owner slots 0 and 1 —
     * neither matches the root's pinned owners, so the root's own M-of-N
     * check must fail (the root never spent, the vault op never authorized) */
    let forged_signers: Vec<(usize, Keypair)> = vec![(0, kp(B_SEED)), (1, kp(C_SEED))];
    let blob = root_owner_blob(&unsigned, &entries, 1, &forged_signers);
    let root_ss = cov_call_opt(&compile_root(&root_prev, &tmpl), "rootAction", vec![root_state_arg(&root_new), Expr::int(0), Expr::bytes(blob)], false);
    let ctrl_ss = cov_call_opt(&ctrl_prev, "ownerControl", vec![state_arg(&vault_new, &VAULT_ID), Expr::int(0)], false);
    let fuel_sig = sign_typed(&unsigned, &entries, 2, &fuel_kp(), SIG_HASH_ALL);

    let mut signed = inputs;
    signed[0].signature_script = ctrl_ss;
    signed[1].signature_script = root_ss;
    signed[2].signature_script = p2pk_sigscript(fuel_sig);
    let tx = Transaction::new(1, signed, outputs, 0, SubnetworkId::default(), 0, vec![]);
    let rr = execute_input_with_covenants(tx.clone(), entries.clone(), 1);
    assert!(rr.is_err(), "the root must refuse an M-of-N blob signed with descendant HD-leaf keys: {rr:?}");
    /* NOTE on input independence: each of a Kaspa transaction's inputs is
     * verified on its OWN script; input 0 (the vault) only checks that the
     * root's OUTPUT bytes commit to the expected byte-exact AUTHORIZE
     * successor — it does not and structurally cannot re-verify input 1's
     * OWN signature material (that would require cross-input signature
     * introspection this covenant model does not have). So input 0 alone
     * may accept even though the root's M-of-N was forged; the SAME
     * transaction is nonetheless INVALID on-chain because Kaspa consensus
     * requires EVERY input's script to verify, and input 1 (asserted above)
     * refuses. This is the intended security boundary: a descendant cannot
     * complete an owner/root operation because it cannot produce a
     * transaction where BOTH inputs verify. */
    let vr = execute_input_with_covenants(tx, entries, 0);
    println!("  REFUSED descendant leaf keys forging the root's M-of-N (owner/root op)  root_input={rr:?} vault_input_alone={vr:?} (whole tx invalid because the root input fails)");
}

