/* CROSS-FAMILY: HD tree presented to the FROZEN v0.5 / CANDIDATE           */
/* v0.7-payment flat controllers, and vice versa                             */
/* ================================================================== */

#[test]
fn hd_cross_family_v05_v07_payment_refuse_an_hd_committed_tree() {
    /* v0.7-payment carries the v0.5 flat leaf format UNCHANGED (0x50563501),
     * so one comparison against v0.7-payment.sil covers v0.5 AND v0.7-payment
     * simultaneously — they are byte-identical in this domain. */
    let owner_pk_unused = ZERO32; // v0.7-payment has no owner key
    let a1 = chain_templates()[0].clone();
    let recip = xonly(&recipient_kp());
    let mut leaf = a1.clone();
    leaf.recipient_root = sha256(&[&RECIP_DOMAIN, &recip]);
    let hd_root = merkle(&[hd_leaf_hash(&leaf)], 0).0;

    let (_tmpl, rpin) = standing_root_pin();
    let tok = token_pin();
    let prev = S { reserve: RESERVE, paused: 0, agent_root: hd_root, policy_nonce: 0 };
    let src = src_v7_payment_raw();
    let mut tsrc = src.to_string();
    tsrc = tsrc.replacen("int feeReserve = initFeeReserve;", &format!("int feeReserve = {};", prev.reserve), 1);
    tsrc = tsrc.replacen("int paused = 0;", &format!("int paused = {};", prev.paused), 1);
    tsrc = tsrc.replacen("byte[32] agentRoot = initAgentRoot;", &format!("byte[32] agentRoot = 0x{};", hx(&prev.agent_root)), 1);
    tsrc = tsrc.replacen("int policyNonce = 0;", &format!("int policyNonce = {};", prev.policy_nonce), 1);
    let leaked: &'static str = leak(tsrc);
    let ctrl_prev = compile_contract(
        leaked,
        &[
            Expr::bytes(VAULT_ID.to_vec()),
            Expr::bytes(DESCRIPTOR_HASH.to_vec()),
            Expr::bytes(tok.token_covid.as_bytes().to_vec()),
            Expr::bytes(tok.template_hash.to_vec()),
            Expr::int(tok.prefix_len),
            Expr::int(tok.state_len),
            Expr::int(tok.suffix_len),
            Expr::bytes(rpin.covid.as_bytes().to_vec()),
            Expr::bytes(rpin.hash.to_vec()),
            Expr::int(rpin.prefix_len),
            Expr::int(rpin.state_len),
            Expr::int(rpin.suffix_len),
            Expr::bytes(recovery_pk().to_vec()),
            Expr::bytes(prev.agent_root.to_vec()),
            Expr::int(prev.reserve),
        ],
        CompileOptions::default(),
    )
    .unwrap_or_else(|e| panic!("compile v0.7-payment: {e:?}"));
    let _ = owner_pk_unused;

    let self_id: [u8; 32] = COV_CTRL.as_bytes().try_into().unwrap();
    let spend = 250i64;
    let self_after = PREV_TOKEN_AMOUNT - spend;
    let tok_prev = compile_kcc20(self_id, IDENTIFIER_COVENANT_ID, PREV_TOKEN_AMOUNT, false, 2);
    let new_state = S { reserve: RESERVE - RESERVE_CONSUMED, ..prev.clone() };
    let ctrl_next = compile_ctrl(src_v7_payment_raw(), &tok, &rpin, &new_state, &VAULT_ID); // placeholder, unused (built below without this call site's state)
    let _ = ctrl_next;

    let fuel = fuel_kp();
    let fuel_pk = xonly(&fuel);
    let tok_self = compile_kcc20(self_id, IDENTIFIER_COVENANT_ID, self_after, false, 2);
    let tok_recipient = compile_kcc20(recip, IDENTIFIER_PUBKEY, spend, false, 2);
    // rebuild the v0.7-payment successor with the SAME templating helper directly
    let mut nsrc = src.to_string();
    nsrc = nsrc.replacen("int feeReserve = initFeeReserve;", &format!("int feeReserve = {};", new_state.reserve), 1);
    nsrc = nsrc.replacen("int paused = 0;", &format!("int paused = {};", new_state.paused), 1);
    nsrc = nsrc.replacen("byte[32] agentRoot = initAgentRoot;", &format!("byte[32] agentRoot = 0x{};", hx(&new_state.agent_root)), 1);
    nsrc = nsrc.replacen("int policyNonce = 0;", &format!("int policyNonce = {};", new_state.policy_nonce), 1);
    let nleaked: &'static str = leak(nsrc);
    let ctrl_succ = compile_contract(
        nleaked,
        &[
            Expr::bytes(VAULT_ID.to_vec()),
            Expr::bytes(DESCRIPTOR_HASH.to_vec()),
            Expr::bytes(tok.token_covid.as_bytes().to_vec()),
            Expr::bytes(tok.template_hash.to_vec()),
            Expr::int(tok.prefix_len),
            Expr::int(tok.state_len),
            Expr::int(tok.suffix_len),
            Expr::bytes(rpin.covid.as_bytes().to_vec()),
            Expr::bytes(rpin.hash.to_vec()),
            Expr::int(rpin.prefix_len),
            Expr::int(rpin.state_len),
            Expr::int(rpin.suffix_len),
            Expr::bytes(recovery_pk().to_vec()),
            Expr::bytes(new_state.agent_root.to_vec()),
            Expr::int(new_state.reserve),
        ],
        CompileOptions::default(),
    )
    .unwrap_or_else(|e| panic!("compile v0.7-payment successor: {e:?}"));

    let outputs = vec![
        cov_out(new_state.reserve, &ctrl_succ, 0, COV_CTRL),
        cov_out(TOKEN_CARRY - RECIPIENT_CARRY, &tok_self, 1, COV_TOKEN),
        cov_out(RECIPIENT_CARRY, &tok_recipient, 1, COV_TOKEN),
        p2pk_out(&fuel_pk, FUEL - (FEE - RESERVE_CONSUMED)),
    ];
    let inputs = vec![input(1, 0, vec![], 600), input(2, 0, vec![], 200), input(3, 0, vec![], 20)];
    let entries = vec![cov_utxo(prev.reserve, &ctrl_prev, COV_CTRL), cov_utxo(TOKEN_CARRY, &tok_prev, COV_TOKEN), UtxoEntry::new(FUEL as u64, p2pk_spk(&fuel_pk), 0, false, None)];
    let unsigned = Transaction::new(1, inputs.clone(), outputs.clone(), 0, SubnetworkId::default(), 0, vec![]);
    let sig = sign_typed(&unsigned, &entries, 0, &kp(A1_SEED), SIG_HASH_ALL);
    let fuel_sig = sign_typed(&unsigned, &entries, 2, &fuel, SIG_HASH_ALL);

    let args: Vec<Expr<'static>> = vec![
        state_arg(&new_state, &VAULT_ID),
        kcc20_state(self_id, IDENTIFIER_COVENANT_ID, self_after, false),
        kcc20_state(recip, IDENTIFIER_PUBKEY, spend, false),
        Expr::bytes(leaf.pk.to_vec()),
        Expr::int(leaf.max_per_spend),
        Expr::int(leaf.period_budget),
        Expr::int(leaf.period_length_daa),
        Expr::int(leaf.period_start_daa),
        Expr::int(leaf.period_spent),
        Expr::int(leaf.max_fee_per_tx),
        Expr::int(leaf.max_carry_kas),
        Expr::bytes(leaf.recipient_root.to_vec()),
        Expr::bytes(vec![]),
        Expr::int(0),
        Expr::int(0),
        Expr::bytes(recip.to_vec()),
        Expr::bytes(vec![]),
        Expr::int(0),
        Expr::bytes(sig),
    ];
    let mut signed = inputs;
    signed[0].signature_script = cov_call_opt(&ctrl_prev, "tokenAgentSpend", args, false);
    signed[1].signature_script = cov_call_opt(&tok_prev, "transfer", vec![vec![kcc20_state(self_id, IDENTIFIER_COVENANT_ID, self_after, false), kcc20_state(recip, IDENTIFIER_PUBKEY, spend, false)].into(), Vec::<Expr>::new().into(), Expr::bytes(vec![0u8])], true);
    signed[2].signature_script = p2pk_sigscript(fuel_sig);
    let tx = Transaction::new(1, signed, outputs, 0, SubnetworkId::default(), 0, vec![]);
    let err = execute_input_with_covenants(tx, entries, 0).expect_err("v0.7-payment (== v0.5 leaf domain) must REFUSE an HD-format committed tree");
    println!("  REFUSED v0.7-payment (v0.5/v0.7 flat leaf domain) driven with an HD-committed agentRoot   {err:?}");
}

/* ================================================================== */
/* MEASUREMENT — redeem geometry, per-op cost, MAX_STACK_SIZE headroom  */
/* ================================================================== */

fn priced(b: &Built, i: usize) -> (u64, u16, u16) {
    let (r, u) = execute_input_measured_priced(b.tx.clone(), b.entries.clone(), i, 1000);
    r.unwrap_or_else(|e| panic!("priced input {i} must accept: {e:?}"));
    let budget = ComputeBudget::checked_covering_script_units(ScriptUnits(u)).expect("budget").0;
    let sigops = post_toccata_p2sh_sig_scanner(&b.tx.inputs[i].signature_script, &b.entries[i].script_public_key);
    (u, budget, sigops as u16)
}
fn padded_run(b: &Built, pad: usize) -> Result<(), TxScriptError> {
    let mut tx = b.tx.clone();
    let mut pushes = ScriptBuilder::new();
    for _ in 0..pad {
        pushes.add_data(&[0x01u8]).unwrap();
    }
    let mut ss = pushes.drain();
    ss.extend_from_slice(&tx.inputs[0].signature_script);
    tx.inputs[0].signature_script = ss;
    execute_input_measured(tx, b.entries.clone(), 0).0
}
fn measure_peak_stack(label: &str, b: &Built) -> usize {
    padded_run(b, 0).unwrap_or_else(|e| panic!("{label}: unpadded run must accept: {e:?}"));
    let exceeds = |pad: usize| matches!(padded_run(b, pad), Err(TxScriptError::StackSizeExceeded(_, _)));
    assert!(exceeds(244), "{label}: padding by 244 must exceed MAX_STACK_SIZE");
    let (mut lo, mut hi) = (1usize, 244usize);
    while lo < hi {
        let mid = (lo + hi) / 2;
        if exceeds(mid) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    let peak = 245 - lo;
    println!("  {label:<58} peak combined stack {peak:>4} / 244  -> headroom {:>4}", 244 - peak);
    peak
}
fn with_covering_budgets(mut c: Scen) -> Scen {
    let b0 = build(&c);
    let n = b0.tx.inputs.len();
    let mut units = Vec::with_capacity(n);
    for i in 0..n {
        let (r, u) = execute_input_measured_priced(b0.tx.clone(), b0.entries.clone(), i, 1000);
        r.unwrap_or_else(|e| panic!("budget pass 1: input {i} must accept: {e:?}"));
        units.push(u);
    }
    let bud = |u: u64| ComputeBudget::checked_covering_script_units(ScriptUnits(u)).expect("covering budget").0;
    c.budgets = (bud(units[0]), if n > 2 { bud(units[1]) } else { 200 }, bud(units[n - 1]));
    let b1 = build(&c);
    for i in 0..n {
        let (r, u) = execute_input_measured_priced(b1.tx.clone(), b1.entries.clone(), i, 1000);
        r.unwrap_or_else(|e| panic!("budget pass 2: input {i} must accept: {e:?}"));
        assert_eq!(u, units[i], "script units must not depend on the committed compute budget");
    }
    c
}
fn mass_of(tx: &Transaction) -> (u64, u64, u64, u64) {
    let mc = MassCalculator::new(1, 10, STORAGE_MASS_PARAMETER);
    let m = mc.calc_non_contextual_masses(tx);
    let size = transaction_estimated_serialized_size(tx);
    let normalized_transient = (m.transient_mass * 500_000).div_ceil(1_000_000);
    (size, m.compute_mass, m.transient_mass, m.compute_mass.max(normalized_transient))
}
fn deep(mut c: Scen) -> Scen {
    c.tree.l1_pad = 4096;
    c.tree.kid_pad = 256;
    for lvl in 0..4 {
        let target = c.recip[lvl].target;
        set_recip(&mut c, lvl, 16, target);
    }
    c.budgets = (60000, 200, 20);
    c
}

#[test]
fn hd_rooted_measurement_redeem_units_mass_sigops_and_stack() {
    println!("\n===== ROOTED HIERARCHICAL DELEGATION (v0.7-payment-hd) — MEASUREMENT =====");

    let (_tmpl, rpin) = standing_root_pin();
    let tok = token_pin();
    let st = S { reserve: RESERVE, paused: 0, agent_root: [0x11; 32], policy_nonce: 0 };
    let v7pay = compile_ctrl(src_v7_payment_raw(), &tok, &rpin, &st, &VAULT_ID); // note: this compiles v0.7-payment-hd's src against v0.7-payment's function set — used ONLY for redeem-length comparison via direct compile below
    let _ = v7pay;
    let baseline = {
        // compile v0.7-payment.sil directly (its OWN constructor call convention is identical) for the redeem-length comparison
        compile_contract(
            src_v7_payment_raw(),
            &[
                Expr::bytes(VAULT_ID.to_vec()),
                Expr::bytes(DESCRIPTOR_HASH.to_vec()),
                Expr::bytes(tok.token_covid.as_bytes().to_vec()),
                Expr::bytes(tok.template_hash.to_vec()),
                Expr::int(tok.prefix_len),
                Expr::int(tok.state_len),
                Expr::int(tok.suffix_len),
                Expr::bytes(rpin.covid.as_bytes().to_vec()),
                Expr::bytes(rpin.hash.to_vec()),
                Expr::int(rpin.prefix_len),
                Expr::int(rpin.state_len),
                Expr::int(rpin.suffix_len),
                Expr::bytes(recovery_pk().to_vec()),
                Expr::bytes(st.agent_root.to_vec()),
                Expr::int(st.reserve),
            ],
            CompileOptions::default(),
        )
        .unwrap()
    };
    let hd = compile_ctrl(src_ctrl_raw(), &tok, &rpin, &st, &VAULT_ID);
    println!("\n[1] REDEEM GEOMETRY");
    println!("  {:<40} | {:>10} | {:>12} | {:>10}", "covenant", "redeem B", "vs v0.7-payment", "state B");
    println!("  {:<40} | {:>10} | {:>12} | {:>10}", "CANDIDATE PolicyVault.v0.7-payment.sil", baseline.script.len(), "-", baseline.state_layout.len);
    println!("  {:<40} | {:>10} | {:>+12} | {:>10}", "CANDIDATE PolicyVault.v0.7-payment-hd.sil", hd.script.len(), hd.script.len() as i64 - baseline.script.len() as i64, hd.state_layout.len);
    assert_eq!(hd.state_layout.len, baseline.state_layout.len, "the mutable state region must be unchanged by composing HD");

    println!("\n[2] PER-OPERATION COST (shallow proofs: agent depth 1, child depth 1, recipient depth 0)");
    println!("  {:<40} | {:>9} | {:>11} | {:>12} | {:>6} | {:>7} | {:>9} | {:>9} | {:>9} | {:>7}", "operation", "sigscr B", "units", "priced units", "budget", "tx B", "compute", "transient", "fee mass", "sig-ops");
    let cases: Vec<(String, Scen)> = vec![
        ("rooted level-1 spend (hdSpend)".into(), honest_spend(1)),
        ("rooted level-2 spend (childSpendL2)".into(), honest_spend(2)),
        ("rooted level-3 spend (childSpendL3)".into(), honest_spend(3)),
        ("rooted delegateSetChildRoot1".into(), honest_dsc(1).0),
        ("rooted delegateSetChildRoot2".into(), honest_dsc(2).0),
    ];
    let mut peaks: Vec<(String, usize)> = vec![];
    for (label, c) in cases {
        let c = with_covering_budgets(c);
        let b = accepts(&label, &c);
        let (units, budget, sigops) = priced(&b, 0);
        let (tx_b, compute, transient, fee_mass) = mass_of(&b.tx);
        println!(
            "  {:<40} | {:>9} | {:>11} | {:>12} | {:>6} | {:>7} | {:>9} | {:>9} | {:>9} | {:>7}",
            label,
            b.tx.inputs[0].signature_script.len(),
            units,
            units, // priced == units here (already priced)
            budget,
            tx_b,
            compute,
            transient,
            fee_mass,
            sigops
        );
        assert!((sigops as u64) <= MAX_STANDARD_P2SH_SIG_OPS, "{label}: static sig-ops {sigops} must stay <= {MAX_STANDARD_P2SH_SIG_OPS}");
        let peak = measure_peak_stack(&label, &b);
        peaks.push((label.clone(), peak));
        assert!(peak <= 244, "{label}: peak combined stack {peak} must not exceed MAX_STACK_SIZE 244");
    }

    println!("\n[3] MAXIMUM-DEPTH SHAPES (agent depth 12, child depth 8 per level, recipient depth 16 per level)");
    let deep_cases: Vec<(String, Scen)> = vec![("rooted level-3 spend (deep)".into(), honest_spend(3)), ("rooted delegateSetChildRoot2 (deep)".into(), honest_dsc(2).0)];
    for (label, c) in deep_cases {
        let c = with_covering_budgets(deep(c));
        let b = accepts(&label, &c);
        let (units, budget, sigops) = priced(&b, 0);
        let (tx_b, compute, transient, fee_mass) = mass_of(&b.tx);
        println!("  {:<40} | {:>9} | {:>11} | {:>12} | {:>6} | {:>7} | {:>9} | {:>9} | {:>9} | {:>7}", label, b.tx.inputs[0].signature_script.len(), units, units, budget, tx_b, compute, transient, fee_mass, sigops);
        let peak = measure_peak_stack(&label, &b);
        assert!(peak <= 244, "{label}: peak combined stack {peak} must not exceed MAX_STACK_SIZE 244");
        /* the probe's finding: proof depth costs bytes, not stack items */
        let shallow_label = if label.contains("level-3") { "rooted level-3 spend (childSpendL3)" } else { "rooted delegateSetChildRoot2" };
        if let Some((_, shallow_peak)) = peaks.iter().find(|(l, _)| l == shallow_label) {
            assert_eq!(peak, *shallow_peak, "{label}: proof depth must not change the peak combined stack (probe finding, design record §6.5)");
        }
    }

    let l3 = peaks.iter().find(|(l, _)| l.contains("level-3")).unwrap().1;
    println!("\n[4] VERDICT: MAXIMUM PROVEN ROOTED LEVEL");
    println!("  level-3 spend (childSpendL3) peak combined stack: {l3} / 244, headroom {}", 244 - l3);
    assert!(l3 <= 244, "level-3 must fit for MAX_LEVEL 3 to be the proven rooted level");
}

/* ================================================================== */
/* PRODUCTION-BYTE integration: the real pv_call_encoder BINARY         */
/* (CLAUDE.md production-byte rule: an encoder that only compiles is    */
/* not proven — its exact output must be driven through the real        */
/* engine, not merely rebuilt in-process. Mirrors the pattern in        */
/* v7_payment_production.rs's `mod encoder`.)                           */
/* ================================================================== */

mod encoder {
    use super::*;
    use std::path::PathBuf;
    use std::process::Command;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn encoder_path() -> PathBuf {
        PathBuf::from(format!("{}/target/debug/pv_call_encoder", env!("CARGO_MANIFEST_DIR")))
    }
    fn tmp_dir() -> PathBuf {
        let unique = format!("{}-{}", std::process::id(), SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos());
        let dir = std::env::temp_dir().join(format!("pv-hd-{unique}"));
        std::fs::create_dir_all(&dir).expect("tmp dir");
        dir
    }
    fn bytes_arg(b: &[u8]) -> serde_json::Value {
        serde_json::json!({"kind": "array", "data": b.iter().map(|x| serde_json::json!({"kind": "byte", "data": x})).collect::<Vec<_>>()})
    }
    fn int_arg(v: i64) -> serde_json::Value {
        serde_json::json!({"kind": "int", "data": v})
    }
    fn ctor_args(tok: &TokenPin, root: &RootPin, s: &S) -> serde_json::Value {
        serde_json::Value::Array(vec![
            bytes_arg(&VAULT_ID),
            bytes_arg(&DESCRIPTOR_HASH),
            bytes_arg(tok.token_covid.as_bytes().as_slice()),
            bytes_arg(&tok.template_hash),
            int_arg(tok.prefix_len),
            int_arg(tok.state_len),
            int_arg(tok.suffix_len),
            bytes_arg(root.covid.as_bytes().as_slice()),
            bytes_arg(&root.hash),
            int_arg(root.prefix_len),
            int_arg(root.state_len),
            int_arg(root.suffix_len),
            bytes_arg(&recovery_pk()),
            bytes_arg(&s.agent_root),
            int_arg(s.reserve),
        ])
    }
    fn successor_json(s: &S) -> serde_json::Value {
        serde_json::json!({"feeReserve": s.reserve, "paused": s.paused, "agentRoot": hx(&s.agent_root), "policyNonce": s.policy_nonce})
    }
    fn kcc20_json(owner: &[u8; 32], ty: u8, amount: i64) -> serde_json::Value {
        serde_json::json!({"ownerIdentifier": hx(owner), "identifierType": ty, "amount": amount, "isMinter": false})
    }
    fn chain_entry_json(l: &HdLeaf, siblings: &[u8], bits: u64, periods_elapsed: i64, recip_siblings: &[u8], recip_bits: u64) -> serde_json::Value {
        serde_json::json!({
            "leaf": hx(&hd_leaf_body(l)),
            "siblings": hx(siblings),
            "pathBits": bits,
            "periodsElapsed": periods_elapsed,
            "recipientSiblings": hx(recip_siblings),
            "recipientPathBits": recip_bits,
        })
    }
    fn run(src: &str, ctor: serde_json::Value, call: serde_json::Value) -> Result<String, String> {
        let dir = tmp_dir();
        let s = dir.join("vault.sil");
        std::fs::write(&s, src).unwrap();
        let a = dir.join("ctor.json");
        std::fs::write(&a, serde_json::to_string(&ctor).unwrap()).unwrap();
        let cj = dir.join("call.json");
        std::fs::write(&cj, serde_json::to_string(&call).unwrap()).unwrap();
        let out = Command::new(encoder_path()).arg(&s).arg(&a).arg(&cj).output().expect("run pv_call_encoder");
        let _ = std::fs::remove_dir_all(&dir);
        if out.status.success() {
            Ok(String::from_utf8(out.stdout).unwrap().trim().to_string())
        } else {
            Err(String::from_utf8_lossy(&out.stderr).trim().to_string())
        }
    }
    fn unhex(s: &str) -> Vec<u8> {
        (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
    }

    fn ctrl_prev_state(c: &Scen, prev_root: [u8; 32]) -> S {
        S { reserve: c.prev_reserve, paused: c.prev_paused, agent_root: prev_root, policy_nonce: c.prev_nonce }
    }
    fn real_signature(c: &Scen, b: &Built) -> Vec<u8> {
        let unsigned = Transaction::new(1, b.tx.inputs.iter().map(|i| TransactionInput { signature_script: vec![], ..i.clone() }).collect(), b.tx.outputs.clone(), c.lock_time, SubnetworkId::default(), 0, vec![]);
        sign_typed(&unsigned, &b.entries, 0, &kp(c.signer_seed), c.sighash)
    }
    fn assert_encoded_matches_and_accepts(label: &str, encoded_hex: String, redeem_script: &[u8], b: &Built) {
        let mut ss = unhex(&encoded_hex);
        ss.extend_from_slice(&push_redeem(redeem_script));
        assert_eq!(ss.len(), b.tx.inputs[0].signature_script.len(), "{label}: the BINARY and the in-process encoder must agree on sigscript length for the SAME honest call");
        let mut inputs = b.tx.inputs.clone();
        inputs[0].signature_script = ss;
        let tx = Transaction::new(1, inputs, b.tx.outputs.clone(), b.tx.lock_time, SubnetworkId::default(), 0, vec![]);
        execute_input_measured(tx, b.entries.clone(), 0).0.unwrap_or_else(|e| panic!("{label}: REAL pv_call_encoder bytes must be ACCEPTED by the engine: {e:?}"));
        println!("  ENCODER -> ENGINE ACCEPTED  {label} (production-byte rule satisfied for the policyvault-0.7-payment-hd arm)");
    }

    /// Rebuild an honest spend at `level` with the SAME in-process encoding
    /// (`build`/`accepts`), then swap ONLY input 0's signature script for the
    /// REAL `pv_call_encoder` BINARY's output and re-execute.
    #[test]
    fn hd_rooted_encoder_production_bytes_every_spend_level_accepted_by_the_engine() {
        assert!(encoder_path().exists(), "build it first: cd tests/vm && cargo build --bin pv_call_encoder");
        for (level, function) in [(1usize, "hdSpend"), (2, "childSpendL2"), (3, "childSpendL3")] {
            let c = honest_spend(level);
            let b = accepts(&format!("{function} (in-process encoding, baseline)"), &c);

            let (_root_tmpl, rpin) = standing_root_pin();
            let tok = token_pin();
            let prev = ctrl_prev_state(&c, b.prev_root);
            let src = templated(src_ctrl_raw(), &prev);
            let ctor = ctor_args(&tok, &rpin, &prev);

            let succ_reserve = c.prev_reserve - c.reserve_consumed;
            let new_state = S { reserve: succ_reserve, ..ctrl_prev_state(&c, b.new_root) };
            let self_id: [u8; 32] = COV_CTRL.as_bytes().try_into().unwrap();
            let self_after = PREV_TOKEN_AMOUNT - c.spend;
            let recipient_pk = xonly(&recipient_kp());
            let chain_json: Vec<serde_json::Value> = b.chain.iter().enumerate().map(|(i, (l, sibs, bits))| chain_entry_json(l, sibs, *bits, c.periods_elapsed[i], &b.recip_chain[i].0, b.recip_chain[i].1)).collect();

            let mut call = serde_json::json!({
                "contractVersion": "policyvault-0.7-payment-hd",
                "function": function,
                "successor": successor_json(&new_state),
                "selfNew": kcc20_json(&self_id, IDENTIFIER_COVENANT_ID, self_after),
                "recipientNew": kcc20_json(&recipient_pk, IDENTIFIER_PUBKEY, c.spend),
                "chain": chain_json,
                "recipientPk": hx(&recipient_pk),
                "signature": hx(&vec![0u8; 65]),
            });
            call["signature"] = serde_json::Value::String(hx(&real_signature(&c, &b)));

            let encoded = run(&src, ctor, call).unwrap_or_else(|e| panic!("the real pv_call_encoder binary must succeed for an honest {function} call: {e}"));
            let redeem = compile_ctrl(src_ctrl_raw(), &tok, &rpin, &prev, &VAULT_ID).script;
            assert_encoded_matches_and_accepts(function, encoded, &redeem, &b);
        }
    }

    /// Rebuild an honest delegation at `level` with the SAME in-process
    /// encoding, then swap input 0's signature script for the REAL
    /// `pv_call_encoder` BINARY's output and re-execute.
    #[test]
    fn hd_rooted_encoder_production_bytes_every_delegation_level_accepted_by_the_engine() {
        assert!(encoder_path().exists(), "build it first: cd tests/vm && cargo build --bin pv_call_encoder");
        for (level, function) in [(1usize, "delegateSetChildRoot1"), (2, "delegateSetChildRoot2")] {
            let (c, _expected_root) = honest_dsc(level);
            let b = accepts(&format!("{function} (in-process encoding, baseline)"), &c);

            let (_root_tmpl, rpin) = standing_root_pin();
            let tok = token_pin();
            let prev = ctrl_prev_state(&c, b.prev_root);
            let src = templated(src_ctrl_raw(), &prev);
            let ctor = ctor_args(&tok, &rpin, &prev);
            let new_state = ctrl_prev_state(&c, b.new_root);

            let mut call = if level == 1 {
                let (parent_leaf, siblings, bits) = &b.chain[0];
                serde_json::json!({
                    "contractVersion": "policyvault-0.7-payment-hd",
                    "function": function,
                    "successor": successor_json(&new_state),
                    "parentLeaf": hx(&hd_leaf_body(parent_leaf)),
                    "siblings": hx(siblings),
                    "pathBits": *bits,
                    "newChildRoot": hx(&c.dsc_new_child_root),
                    "signature": hx(&vec![0u8; 65]),
                })
            } else {
                let (a1, siblings1, bits1) = &b.chain[0];
                let (parent_leaf, siblings2, bits2) = &b.chain[1];
                serde_json::json!({
                    "contractVersion": "policyvault-0.7-payment-hd",
                    "function": function,
                    "successor": successor_json(&new_state),
                    "chain": [{"leaf": hx(&hd_leaf_body(a1)), "siblings": hx(siblings1), "pathBits": *bits1}],
                    "parentLeaf": hx(&hd_leaf_body(parent_leaf)),
                    "siblings2": hx(siblings2),
                    "pathBits2": *bits2,
                    "newChildRoot": hx(&c.dsc_new_child_root),
                    "signature": hx(&vec![0u8; 65]),
                })
            };
            call["signature"] = serde_json::Value::String(hx(&real_signature(&c, &b)));

            let encoded = run(&src, ctor, call).unwrap_or_else(|e| panic!("the real pv_call_encoder binary must succeed for an honest {function} call: {e}"));
            let redeem = compile_ctrl(src_ctrl_raw(), &tok, &rpin, &prev, &VAULT_ID).script;
            assert_encoded_matches_and_accepts(function, encoded, &redeem, &b);
        }
    }

    #[test]
    fn hd_rooted_encoder_fails_closed_on_out_of_domain_intent() {
        assert!(encoder_path().exists(), "build it first: cd tests/vm && cargo build --bin pv_call_encoder");
        let prev = S { reserve: RESERVE, paused: 0, agent_root: ZERO32, policy_nonce: 0 };
        let (_root_tmpl, rpin) = standing_root_pin();
        let tok = token_pin();
        let src = templated(src_ctrl_raw(), &prev);
        let ctor = ctor_args(&tok, &rpin, &prev);

        for (label, call) in [
            ("ownerControl selector out of range (5)", serde_json::json!({"contractVersion": "policyvault-0.7-payment-hd", "function": "ownerControl", "opSelector": 5, "successor": successor_json(&prev)})),
            ("ownerControl carrying a signature", serde_json::json!({"contractVersion": "policyvault-0.7-payment-hd", "function": "ownerControl", "opSelector": 0, "signature": hx(&[0u8; 65]), "successor": successor_json(&prev)})),
            ("ownerRecover carrying opSelector", serde_json::json!({"contractVersion": "policyvault-0.7-payment-hd", "function": "ownerRecover", "opSelector": 0, "recipientNew": kcc20_json(&recovery_pk(), IDENTIFIER_PUBKEY, 1)})),
            ("unknown function", serde_json::json!({"contractVersion": "policyvault-0.7-payment-hd", "function": "childSpendL4"})),
            ("unknown contractVersion", serde_json::json!({"contractVersion": "policyvault-0.7-payment", "function": "hdSpend"})),
        ] {
            let result = run(&src, ctor.clone(), call);
            assert!(result.is_err(), "{label}: the encoder must refuse out-of-domain intent, not silently encode a wrong call");
            println!("  ENCODER REFUSED {label:<45} {}", result.unwrap_err());
        }
    }
}
